fn format_session_append(kind: Option<&str>, content: &str) -> String {
    match kind {
        Some("handoff") => format!("[voice handoff] {content}"),
        Some("planner_handoff") => format!("[voice planner handoff]\n\n{content}"),
        _ => content.to_string(),
    }
}

